/**
 * Minimal HTML-escaping for text content.
 * Escapes &, <, >, ", and ' so interpolated text can never form markup.
 */
function esc(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function cellContent(row, column) {
  const raw = row[column.key];
  if (raw === undefined || raw === null) return '';
  return esc(raw);
}

/**
 * Render an accessible HTML table.
 *
 * @param {object} options
 * @param {string} options.caption - Table caption.
 * @param {Array<{key: string, label: string, numeric?: boolean, rowHeader?: boolean}>} options.columns
 * @param {Array<object>} options.rows - Data rows keyed by column key.
 * @param {object} [options.summaryRow] - Optional footer row keyed by column key.
 * @returns {string} HTML table markup.
 */
export function renderTable({ caption, columns, rows, summaryRow }) {
  const lines = [];
  lines.push('<table>');
  lines.push(`  <caption>${esc(caption)}</caption>`);
  lines.push('  <thead>');
  lines.push('    <tr>');
  for (const column of columns) {
    lines.push(
      `      <th scope="col"${column.numeric ? ' class="num"' : ''}>${esc(column.label)}</th>`
    );
  }
  lines.push('    </tr>');
  lines.push('  </thead>');
  lines.push('  <tbody>');
  for (const row of rows) {
    lines.push('    <tr>');
    for (const column of columns) {
      const content = cellContent(row, column);
      if (column.rowHeader) {
        lines.push(`      <th scope="row">${content}</th>`);
      } else {
        lines.push(`      <td${column.numeric ? ' class="num"' : ''}>${content}</td>`);
      }
    }
    lines.push('    </tr>');
  }
  lines.push('  </tbody>');
  if (summaryRow) {
    lines.push('  <tfoot>');
    lines.push('    <tr>');
    for (const column of columns) {
      const content = cellContent(summaryRow, column);
      lines.push(`      <td${column.numeric ? ' class="num"' : ''}>${content}</td>`);
    }
    lines.push('    </tr>');
    lines.push('  </tfoot>');
  }
  lines.push('</table>');
  return lines.join('\n');
}

