import { describe, expect, it } from 'vitest';
import * as cheerio from 'cheerio';
import { renderTable } from '../src/table.js';

const columns = [
  { key: 'product', label: 'Product', rowHeader: true },
  { key: 'price', label: 'Price', numeric: true },
];

const rows = [
  { product: 'Widget', price: 42 },
  { product: 'Gadget', price: 7.5 },
];

describe('renderTable', () => {
  it('renders the caption text', () => {
    const $ = cheerio.load(renderTable({ caption: 'Inventory', columns, rows }));
    expect($('table > caption').text()).toBe('Inventory');
  });

  it('marks column headers with scope="col"', () => {
    const $ = cheerio.load(renderTable({ caption: 'c', columns, rows }));
    const colHeaders = $('thead th');
    expect(colHeaders).toHaveLength(2);
    expect(colHeaders.eq(0).text()).toBe('Product');
    expect(colHeaders.attr('scope')).toBe('col');
    expect(colHeaders.eq(1).attr('scope')).toBe('col');
  });

  it('marks rowHeader column tbody cells as th with scope="row"', () => {
    const $ = cheerio.load(renderTable({ caption: 'c', columns, rows }));
    const bodyRows = $('tbody tr');
    expect(bodyRows).toHaveLength(2);
    // First cell is a row header
    expect(bodyRows.eq(0).find('th')).toHaveLength(1);
    expect(bodyRows.eq(0).find('th[scope="row"]').text()).toBe('Widget');
    // Second cell stays a td
    expect(bodyRows.eq(0).find('td')).toHaveLength(1);
    expect(bodyRows.eq(0).find('td[scope]')).toHaveLength(0);
  });

  it('adds class num to numeric header and data cells only', () => {
    const $ = cheerio.load(renderTable({ caption: 'c', columns, rows }));
    expect($('thead th.num')).toHaveLength(1);
    expect($('tbody td.num')).toHaveLength(2);
    expect($('tbody td.num').eq(0).text()).toBe('42');
    expect($('tbody td:not(.num)')).toHaveLength(0); // product cell is th
    expect($('tbody th.num')).toHaveLength(0);
  });

  it('escapes HTML in all text content', () => {
    const evilColumns = [{ key: 'name', label: '<b>Name</b>', rowHeader: true }];
    const evilRows = [
      { name: '<script>alert(1)</script>' },
      { name: '"quoted" & <em>styled</em>' },
    ];
    const html = renderTable({ caption: 'XSS <test>', columns: evilColumns, rows: evilRows });
    const $ = cheerio.load(html);

    // Raw markup must contain escaped entities, not executable tags
    expect(html).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(html).not.toContain('<script>');
    expect($('script')).toHaveLength(0);
    expect($('caption').text()).toBe('XSS <test>');
    expect($('thead th').first().text()).toBe('<b>Name</b>');
    expect($('tbody th[scope="row"]').first().text()).toBe('<script>alert(1)</script>');
    expect($('tbody th[scope="row"]').last().text()).toBe('"quoted" & <em>styled</em>');
  });

  it('includes tfoot when summaryRow exists', () => {
    const summaryRow = { product: 'Total', price: 49.5 };
    const html = renderTable({ caption: 'c', columns, rows, summaryRow });
    const $ = cheerio.load(html);
    expect($('tfoot')).toHaveLength(1);
    expect($('tfoot th')).toHaveLength(0);
    expect($('tfoot tr td')).toHaveLength(2);
    expect($('tfoot td.num').text()).toBe('49.5');
    expect($('tfoot td').first().text()).toBe('Total');
  });

  it('omits tfoot when summaryRow is absent', () => {
    const $ = cheerio.load(renderTable({ caption: 'c', columns, rows }));
    expect($('tfoot')).toHaveLength(0);
    expect($('table').children().map((_, el) => $(el).get(0).tagName).get())).toEqual([
      'caption',
      'thead',
      'tbody',
    ]);
  });

  it('renders empty values as empty cells', () => {
    const $ = cheerio.load(
      renderTable({ caption: 'c', columns, rows: [{ product: null }] })
    );
    expect($('tbody td.num').text()).toBe('');
  });
});

